def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_aggressive = 0
    weak_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                weak_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 120 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if supply_tight:
        urgency += 2
    elif not supply_loose:
        urgency += 1

    if day >= 8:
        urgency += 1

    if highest_prev >= 120:
        if urgency <= 1:
            bid = 8.0 if supply_loose else 12.0
        elif urgency <= 3:
            bid = 28.0 if supply_loose else 42.0
        else:
            bid = 78.0 if supply_loose else 96.0
    else:
        if urgency <= 1:
            bid = 18.0 if supply_loose else 24.0
        elif urgency <= 3:
            bid = max(38.0, avg_prev + 4.0)
        else:
            bid = max(65.0, highest_prev + 6.0)

    if weak_opp >= 2 and urgency <= 2:
        bid *= 0.85

    if rich_aggressive >= 2 and urgency <= 2:
        bid *= 0.8

    reserve_target = 0.0
    days_left = max(0, 10 - day)
    if hp > 4 and no_water_days == 0:
        reserve_target = min(140.0, days_left * 10.0)
    elif hp > 2:
        reserve_target = min(90.0, days_left * 6.0)

    max_affordable = max(0.0, budget - reserve_target)
    if urgency >= 4:
        max_affordable = budget
    elif max_affordable < 5.0:
        max_affordable = min(budget, 20.0)

    bid = min(bid, max_affordable)

    if urgency >= 5:
        bid = max(bid, min(budget, 90.0))
    elif urgency >= 3:
        bid = max(bid, min(budget, 45.0))

    if supply_loose and urgency <= 1:
        bid = min(bid, 20.0)

    if bid < 0:
        bid = 0.0

    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_competitive_bid = DAILY_SALARY * 0.85 
    bid = base_competitive_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        bid = max(base_competitive_bid, highest_prev_bid + 5.0)
        bid = min(bid, DAILY_SALARY * 1.05) 

    if my_status['hp'] <= 3: 
        bid = DAILY_SALARY * 0.99
    elif my_status['hp'] <= 7: 
        bid = max(bid, DAILY_SALARY * 0.9) 

    final_bid = min(my_status['budget'], bid)

    if my_status['budget'] <= 0:
        return 0.0

    if final_bid < DAILY_SALARY * 0.1 and my_status['budget'] > 0 and my_status['no_water_days'] > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.1)

    return final_bid

